contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, address logAddr) public payable {
        require(true);

        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }

        bool setMinSumReverted;
        c.SetMinSum(v1); bool __rev1 = __ESBMC_reverted(); if (__rev1) { setMinSumReverted = true; } else { setMinSumReverted = false; }

        bool setLogFileReverted;
        c.SetLogFile(logAddr); bool __rev2 = __ESBMC_reverted(); if (__rev2) { setLogFileReverted = true; } else { setLogFileReverted = false; }

        assert(!initReverted && setMinSumReverted && setLogFileReverted);
    }

    receive() external payable {}
}

